#pragma once
// Include the sealed Hall owner's axial_surface_path_port.hpp first. This
// adapter uses its actual Path/gather/deposit; it defines no replacement mesh.
#include "trial_source_binding.hpp"
namespace electrode_heat_v3 {
struct HandoffTrial {GapParticle particle;foil::Hit boundary;foil::SurfacePathReceipt current;V3 displacement_m{};double handoff_time_s=0,remaining_duration_s=0,endpoint_time_s=0,kinetic_change_J=0;};
class AxialTrialField final:public TrialField {
 std::shared_ptr<const axial::Mesh> mesh_;const foil::Vec E_,B_;std::string values_hash_;
 static std::string fingerprint(const foil::Vec&v){std::uint64_t h=14695981039346656037ULL;for(double x:v){auto bits=std::bit_cast<std::uint64_t>(x);for(int i=0;i<8;++i){h^=(bits>>(8*i))&255;h*=1099511628211ULL;}}return std::to_string(h);}
 FieldSample at(V3 x,V3 D)const{axial::Path p(*mesh_,x,D);return {p.gather_E(E_),p.gather_B(B_)};}
public:
 AxialTrialField(std::shared_ptr<const axial::Mesh>g,TrialFrame f,foil::Vec E,foil::Vec B):TrialField(std::move(f)),mesh_(std::move(g)),E_(std::move(E)),B_(std::move(B)){eh::need(mesh_&&E_.size()==std::size_t(mesh_->ne)&&B_.size()==std::size_t(mesh_->nb)&&foil::finite(E_)&&foil::finite(B_),"actual immutable Hall midpoint arrays required");values_hash_=fingerprint(E_)+"/"+fingerprint(B_);}
 const std::string& values_fingerprint()const{return values_hash_;}
 const foil::Vec& total_mid_E()const{return E_;}const foil::Vec& total_mid_B()const{return B_;}
 bool matches_trial(const TrialFrame&owner_frame,const foil::Vec&owner_E,const foil::Vec&owner_B)const{return frame()==owner_frame&&values_hash_==fingerprint(owner_E)+"/"+fingerprint(owner_B);}
 FieldSample sample(const PrecisionPath&p)const override{eh::need(finite(p.origin_m)&&finite(p.from_relative_m)&&finite(p.to_relative_m)&&finite(p.displacement_m),"nonfinite precise source path");for(int d=0;d<3;++d)eh::need(p.displacement_m[d]==p.to_relative_m[d]-p.from_relative_m[d],"precise displacement does not match retained relative endpoints");return at(p.absolute_from(),p.displacement_m);}
 FieldSample surface(V3 x,V3 n)const override{int axes=0;V3 grid_origin{-mesh_->side/2,-mesh_->side/2,mesh_->zmin},spacing{mesh_->dx,mesh_->dy,mesh_->dz};for(int d=0;d<3;++d){eh::need(n[d]==0||std::abs(n[d])==1,"axis-aligned admitted material normal required");if(n[d]){++axes;double coordinate=(x[d]-grid_origin[d])/spacing[d],plane=std::round(coordinate);if(std::abs(coordinate-plane)<=64*eh::eps*std::max(1.,std::abs(coordinate))){bool entered=false;for(int step=0;step<64;++step){x[d]=std::nextafter(x[d],n[d]>0?INFINITY:-INFINITY);double a=(x[d]-grid_origin[d])/spacing[d];if(n[d]>0?a>plane:a<plane){entered=true;break;}}eh::need(entered,"one-sided field limit unresolved at coordinate precision");}}}eh::need(axes==1,"one material normal axis required");return at(x,{});}
 bool admits_normal_quantum_bridge(const PrecisionPath&p,V3 n)const override{int axis=-1;for(int d=0;d<3;++d)if(p.displacement_m[d]!=0){if(axis>=0||std::abs(n[d])!=1||p.displacement_m[d]*n[d]<=0)return false;axis=d;}if(axis<0)return false;V3 grid_origin{-mesh_->side/2,-mesh_->side/2,mesh_->zmin},spacing{mesh_->dx,mesh_->dy,mesh_->dz};double a=(p.absolute_from()[axis]-grid_origin[axis])/spacing[axis],nearest=std::round(a);if(std::abs(a-nearest)<=64*eh::eps*std::max(1.,std::abs(a)))a=nearest;double b=a+p.displacement_m[axis]/spacing[axis];int cell=p.displacement_m[axis]>0?int(std::floor(a)):int(std::ceil(a))-1;return p.displacement_m[axis]>0?b<cell+1:b>cell;}
 HandoffTrial handoff_remainder(const Candidate&source,const GapParticle&canonical,bool qualification=false)const {
  eh::need(source.field.get()==this&&source.heat_owner&&preflight(source,*source.heat_owner,source.field,qualification)&&source.state.native.status==se::LayerStatus::PICHandedOff,"actual current-trial handoff required");const auto&n=source.state.native;eh::need(canonical.id==source.canonical_particle_id&&canonical.mass_kg==se::me&&canonical.charge_C==-se::qe&&canonical.weight==n.particle.weight,"canonical/source electron species, ID or weight mismatch");HandoffTrial r;r.particle=canonical;r.particle.position_m=source.state.surface_origin_m;for(int d=0;d<3;++d)r.particle.position_m[d]+=n.position_from_surface_m[d];r.particle.proper_velocity_m_s=n.particle.proper_velocity_m_s;r.handoff_time_s=n.current_time_s;r.remaining_duration_s=frame().end_s-r.handoff_time_s;r.endpoint_time_s=r.handoff_time_s;r.current={foil::Vec(mesh_->ne),foil::Vec(mesh_->nn)};eh::need(r.remaining_duration_s>=0&&r.remaining_duration_s<=frame().dt_s,"handoff outside common interval");if(r.remaining_duration_s==0)return r;const auto initial=r.particle;auto motion=axial::push(*mesh_,initial,E_,B_,r.remaining_duration_s);r.particle=motion.particle;r.displacement_m=motion.D;r.boundary=motion.hit;r.endpoint_time_s=r.handoff_time_s+motion.flight_s;axial::Path path(*mesh_,initial.position_m,motion.D);auto E=path.gather_E(E_),B=path.gather_B(B_);eh::need(frame().dt_s*std::abs(initial.charge_C/initial.mass_kg)*norm(B)<=.05,"handoff retained full-common-interval gyro guard failed");double charge=initial.weight*initial.charge_C;path.deposit(r.current.current_load_C_m_s,charge,motion.D,frame().dt_s);axial::point_deposit(*mesh_,r.current.endpoint_charge_impulse_C,initial.position_m,-charge);axial::point_deposit(*mesh_,r.current.endpoint_charge_impulse_C,r.particle.position_m,charge);double W=charge*dot(E,motion.D),K0=pic_kinetic_energy_J(initial)*initial.weight,K1=pic_kinetic_energy_J(r.particle)*r.particle.weight;r.kinetic_change_J=K1-K0;r.current.field_work_J=W;r.current.claimed_field_work_J=r.kinetic_change_J;r.current.work_defect_J=frame().dt_s*foil::dot(E_,r.current.current_load_C_m_s)-r.kinetic_change_J;auto divergence=mesh_->gradient_transpose(r.current.current_load_C_m_s);for(int i=0;i<mesh_->nn;++i)r.current.continuity_C=std::max(r.current.continuity_C,std::abs(r.current.endpoint_charge_impulse_C[i]-frame().dt_s*divergence[i]));double bound=1e-10*(std::abs(W)+std::abs(r.kinetic_change_J))+128*eh::eps*(K0+K1);if(!(std::abs(r.current.work_defect_J)<=bound&&r.current.continuity_C<=1e-12*std::abs(charge))){std::ostringstream message;message<<std::setprecision(17)<<"actual handoff remainder work/continuity failed W="<<W<<" dK="<<r.kinetic_change_J<<" defect="<<r.current.work_defect_J<<" bound="<<bound<<" continuity="<<r.current.continuity_C<<" charge="<<charge<<" remaining="<<r.remaining_duration_s;eh::need(false,message.str());}return r;
 }
 foil::SurfacePathReceipt import(std::span<const Candidate>sources,const std::set<std::uint64_t>&excluded,bool qualification=false)const{
  foil::SurfacePathReceipt r{foil::Vec(mesh_->ne),foil::Vec(mesh_->nn)};double gross=0,work_scale=0;
  std::map<std::uint64_t,PrecisionPath>previous;std::set<std::tuple<std::uint64_t,std::string,std::uint64_t>>events;
  for(const auto&c:sources){eh::need(c.field.get()==this&&c.heat_owner&&preflight(c,*c.heat_owner,c.field,qualification)&&excluded.contains(c.canonical_particle_id),"foreign/stale trial source or missing canonical motion exclusion");eh::need(events.emplace(c.canonical_particle_id,c.heat.producer,c.heat.sequence).second,"duplicate source event current");
   double candidate_work=0,candidate_activity=0;for(const auto&p:c.paths){candidate_work+=p.field_work_J;candidate_activity+=std::abs(p.field_work_J);eh::need(p.start_s>=frame().begin_s&&p.end_s<=frame().end_s&&p.end_s>=p.start_s&&std::isfinite(p.charge_C)&&std::isfinite(p.field_work_J),"precise path outside common interval");auto last=previous.find(c.canonical_particle_id);if(last!=previous.end())eh::need(last->second.origin_m==p.origin_m&&last->second.to_relative_m==p.from_relative_m&&last->second.end_s<=p.start_s&&last->second.charge_C==p.charge_C,"source relative sequence/charge/origin changed");previous[c.canonical_particle_id]=p;
    auto fields=sample(p);axial::Path path(*mesh_,p.absolute_from(),p.displacement_m);path.deposit(r.current_load_C_m_s,p.charge_C,p.displacement_m,frame().dt_s);axial::point_deposit(*mesh_,r.endpoint_charge_impulse_C,p.absolute_from(),-p.charge_C);axial::point_deposit(*mesh_,r.endpoint_charge_impulse_C,p.absolute_to(),p.charge_C);double W=p.charge_C*dot(fields.E,p.displacement_m);r.field_work_J+=W;r.claimed_field_work_J+=p.field_work_J;work_scale+=std::abs(p.field_work_J);for(int d=0;d<3;++d)work_scale+=std::abs(p.charge_C*fields.E[d]*p.displacement_m[d]);gross+=std::abs(p.charge_C);if(p.start_s==p.end_s)++r.zero_duration_bridges;
   }eh::need(std::abs(candidate_work-c.exchange.field_work_J)<=1e-10*(candidate_activity+std::abs(c.exchange.field_work_J))&&c.heat.source_field_work_J==c.exchange.field_work_J,"source exchange and path-work receipts differ");if(!c.paths.empty())eh::need(c.state.native.position_from_surface_m==c.paths.back().to_relative_m&&c.state.native.current_time_s==c.paths.back().end_s,"source endpoint does not match last precise path");
  }
  auto div=mesh_->gradient_transpose(r.current_load_C_m_s);for(int n=0;n<mesh_->nn;++n)r.continuity_C=std::max(r.continuity_C,std::abs(r.endpoint_charge_impulse_C[n]-frame().dt_s*div[n]));r.work_defect_J=frame().dt_s*foil::dot(E_,r.current_load_C_m_s)-r.claimed_field_work_J;eh::need(r.continuity_C<=1e-12*gross,"precise source charge continuity failed");eh::need(std::abs(r.work_defect_J)<=1e-10*work_scale,"Hall midpoint current/work differs from actual source work; reject, never repair energy");return r;
 }
};
}
